/// The stripped serde wire shape of the GraphQL input — both the journal `payload` column and the
/// domain command deserialize from it (generated from the same commands.yaml, camelCase). `null`s
/// are stripped first — an unset GraphQL optional serializes as an explicit null, while the domain
/// payloads model absence as a MISSING key (`Option` fields / `#[serde(default)]` arrays).
fn command_payload(input: &impl serde::Serialize) -> async_graphql::Result<serde_json::Value> {
    let mut value = serde_json::to_value(input).map_err(|e| async_graphql::Error::new(e.to_string()))?;
    strip_nulls(&mut value);
    Ok(value)
}

fn strip_nulls(value: &mut serde_json::Value) {
    match value {
        serde_json::Value::Object(map) => {
            map.retain(|_, v| !v.is_null());
            for v in map.values_mut() {
                strip_nulls(v);
            }
        }
        serde_json::Value::Array(items) => {
            for v in items.iter_mut() {
                strip_nulls(v);
            }
        }
        _ => {}
    }
}

/// `RequestRole` → the scalars.yaml UserType TEXT value (ADR-20260728: enums are stored verbatim).
fn role_text(role: &crate::graphql::acl::RequestRole) -> &'static str {
    use crate::graphql::acl::RequestRole as R;
    match role {
        R::Public => "PUBLIC",
        R::Customer => "CUSTOMER",
        R::RestaurantAccount => "RESTAURANT_ACCOUNT",
        R::Restaurant => "RESTAURANT",
        R::Rider => "RIDER",
        R::Admin => "ADMIN",
        R::External => "EXTERNAL",
    }
}

/// The EFFECTIVE technical envelope of one mutation request (ADR-20260720-015500): what the client
/// supplied via MetadataInput/headers, completed server-side (UUIDv7) and echoed back verbatim in
/// the MutationAcceptance.
pub(crate) struct RequestEnvelope {
    pub message_id: uuid::Uuid,
    pub correlation_id: uuid::Uuid,
    pub cause_id: Option<uuid::Uuid>,
    pub session_id: Option<uuid::Uuid>,
    pub trace_id: Option<String>,
    pub user_id: Option<uuid::Uuid>,
    pub user_type: String,
}

fn request_envelope(ctx: &async_graphql::Context<'_>, metadata: &Option<MetadataInput>) -> RequestEnvelope {
    let principal = ctx.data_opt::<crate::auth::Principal>();
    let user_id = principal
        .and_then(|p| p.user_id.as_deref())
        .and_then(|s| uuid::Uuid::parse_str(s).ok());
    let user_type = principal.map(|p| role_text(&p.role)).unwrap_or("PUBLIC").to_string();
    let session_id = ctx.data_opt::<crate::graphql::session::SessionHeader>().and_then(|s| s.0);
    let trace_id = ctx.data_opt::<crate::graphql::session::TraceContext>().and_then(|t| t.0.clone());
    // Client-suppliable ids validate structurally at scalar parse time; anything missing is
    // server-generated (time-ordered UUIDv7) and the correlation defaults to the messageId.
    let message_id = metadata
        .as_ref()
        .and_then(|m| m.message_id.as_ref())
        .map(|v| v.0)
        .unwrap_or_else(uuid::Uuid::now_v7);
    let correlation_id = metadata
        .as_ref()
        .and_then(|m| m.correlation_id.as_ref())
        .map(|v| v.0)
        .unwrap_or(message_id);
    let cause_id = metadata.as_ref().and_then(|m| m.cause_id.as_ref()).map(|v| v.0);
    RequestEnvelope { message_id, correlation_id, cause_id, session_id, trace_id, user_id, user_type }
}

/// The uniform acceptance payload from the effective envelope.
fn acceptance(env: &RequestEnvelope, status: OperationStatus, duplicate: bool) -> MutationAcceptance {
    MutationAcceptance {
        message_id: MessageId(env.message_id),
        correlation_id: CorrelationId(env.correlation_id),
        cause_id: env.cause_id.map(CauseId),
        session_id: env.session_id.map(SessionId),
        trace_id: env.trace_id.clone().map(TraceId),
        operation_status: status,
        duplicate,
    }
}

/// `command_journal` lifecycle → the caller-facing OperationStatus (RECEIVED reads as PENDING).
pub(crate) fn journal_status_api(s: domain::generated::scalars::CommandJournalStatus) -> OperationStatus {
    use domain::generated::scalars::CommandJournalStatus as J;
    match s {
        J::RECEIVED => OperationStatus::PENDING,
        J::SUCCEEDED => OperationStatus::SUCCEEDED,
        J::REJECTED => OperationStatus::REJECTED,
        J::FAILED => OperationStatus::FAILED,
    }
}

/// A `command_journal` row → the API Operation shape (`operationStatus` / `operationStatusChanged`).
pub(crate) fn operation_from_journal(row: &application::journal::CommandJournalRow) -> Operation {
    let error_code = row
        .error
        .as_ref()
        .and_then(|e| e.get("code"))
        .and_then(|c| c.as_str())
        .map(str::to_owned);
    let message = match (&error_code, row.error.as_ref().and_then(|e| e.get("context"))) {
        (Some(code), Some(context)) => domain::generated::errors::message_en(code, context),
        _ => None,
    };
    Operation {
        message_id: MessageId(row.entry.message_id),
        correlation_id: CorrelationId(row.entry.correlation_id),
        status: journal_status_api(row.status),
        error_code,
        message,
        occurred_at: row.completed_at.unwrap_or(row.received_at),
    }
}

/// The operation ownership scope (ADR-20260720-015500): ADMIN, the journaling actor (JWT subject),
/// or the journaling session (X-SESSION-ID). Callers resolve null / an empty stream on false — the
/// PUBLIC surface must not become an existence oracle.
pub(crate) fn operation_owned(
    ctx: &async_graphql::Context<'_>,
    row: &application::journal::CommandJournalRow,
) -> bool {
    let admin = matches!(
        ctx.data_opt::<crate::graphql::acl::RequestRole>(),
        Some(crate::graphql::acl::RequestRole::Admin)
    );
    let principal_uuid = ctx
        .data_opt::<crate::auth::Principal>()
        .and_then(|p| p.user_id.as_deref())
        .and_then(|s| uuid::Uuid::parse_str(s).ok());
    let session = ctx.data_opt::<crate::graphql::session::SessionHeader>().and_then(|s| s.0);
    admin
        || (principal_uuid.is_some() && principal_uuid == row.entry.user_id)
        || (session.is_some() && session == row.entry.session_id)
}

/// `inbound_messages` lifecycle → the caller-facing OperationStatus (#242 mailbox era):
/// RECEIVED/SCHEDULED read as PENDING; IGNORED/DUPLICATE are the aggregate's no-change/redelivery
/// verdicts — success from the caller's seat; CANCELLED can only be a withdrawn reminder — a
/// command never reaches it, mapped FAILED defensively.
pub(crate) fn mailbox_status_api(s: domain::generated::scalars::InboundMessageStatus) -> OperationStatus {
    use domain::generated::scalars::InboundMessageStatus as M;
    match s {
        M::RECEIVED | M::SCHEDULED => OperationStatus::PENDING,
        M::SUCCEEDED | M::IGNORED | M::DUPLICATE => OperationStatus::SUCCEEDED,
        M::REJECTED => OperationStatus::REJECTED,
        M::FAILED | M::CANCELLED => OperationStatus::FAILED,
    }
}

/// A mailbox status row → the API Operation shape (`operationStatus` on post-flip rows).
pub(crate) fn operation_from_mailbox(row: &application::mailbox::MailboxStatusRow) -> Operation {
    let error_code = row
        .error
        .as_ref()
        .and_then(|e| e.get("code"))
        .and_then(|c| c.as_str())
        .map(str::to_owned);
    let message = match (&error_code, row.error.as_ref().and_then(|e| e.get("context"))) {
        (Some(code), Some(context)) => domain::generated::errors::message_en(code, context),
        _ => None,
    };
    Operation {
        message_id: MessageId(row.message_id),
        correlation_id: CorrelationId(row.correlation_id),
        status: mailbox_status_api(row.status),
        error_code,
        message,
        occurred_at: row.completed_at.unwrap_or(row.received_at),
    }
}

/// The mailbox row's ownership scope — same contract as [`operation_owned`] (ADR-20260720-015500).
pub(crate) fn mailbox_operation_owned(
    ctx: &async_graphql::Context<'_>,
    row: &application::mailbox::MailboxStatusRow,
) -> bool {
    let admin = matches!(
        ctx.data_opt::<crate::graphql::acl::RequestRole>(),
        Some(crate::graphql::acl::RequestRole::Admin)
    );
    let principal_uuid = ctx
        .data_opt::<crate::auth::Principal>()
        .and_then(|p| p.user_id.as_deref())
        .and_then(|s| uuid::Uuid::parse_str(s).ok());
    let session = ctx.data_opt::<crate::graphql::session::SessionHeader>().and_then(|s| s.0);
    admin
        || (principal_uuid.is_some() && principal_uuid == row.user_id)
        || (session.is_some() && session == row.session_id)
}

/// The spawned handler's terminal transition: complete the journal row and publish the update.
/// REJECTED = an anticipated errors.yaml rejection (surfaced as Operation.errorCode); FAILED = the
/// catalogued generic Internal (adapter detail never leaks).
async fn complete_operation(
    journal: std::sync::Arc<dyn application::journal::CommandJournal>,
    bus: infrastructure::OperationStatusBus,
    message_id: uuid::Uuid,
    correlation_id: uuid::Uuid,
    outcome: Result<(), domain::shared::errors::DomainError>,
    journaled_at: std::time::Instant,
) {
    use domain::generated::scalars::CommandJournalStatus as J;
    use domain::shared::errors::DomainError;
    let (status, error, error_code, message) = match outcome {
        Ok(()) => (J::SUCCEEDED, None, None, None),
        Err(DomainError::Rejected { code, context }) => {
            let msg = domain::generated::errors::message_en(&code, &context).unwrap_or_else(|| code.clone());
            let error = serde_json::json!({ "code": code, "context": context });
            (J::REJECTED, Some(error), Some(code), Some(msg))
        }
        // Legacy "<Code>: <detail>" string invariants (interim adapters): a catalogued prefix is a
        // rejection; anything else — and every Repository failure — is a technical failure.
        Err(DomainError::Invariant(msg)) => {
            let code = msg.split(':').next().map(str::trim).unwrap_or("").to_string();
            if domain::generated::errors::find(&code).is_some() {
                let error = serde_json::json!({ "code": code, "context": { "detail": msg } });
                (J::REJECTED, Some(error), Some(code), Some(msg))
            } else {
                internal_completion()
            }
        }
        Err(DomainError::Repository(_)) => internal_completion(),
    };
    // command_completion_ms{status} — journal insert to terminal status, with REJECTED and FAILED kept
    // apart: a business rejection is the system working, a technical failure is not, and one histogram
    // averaging both hides each behind the other.
    telemetry::meters::acceptance::completed(
        journal_status_label(status),
        journaled_at.elapsed().as_secs_f64() * 1000.0,
    );
    if let Err(e) = journal.complete(message_id, status, error).await {
        // The command RAN; only the record of its outcome failed to persist. That leaves the row in
        // RECEIVED for the stale sweep to flip to FAILED, so a caller polling operationStatus is told
        // something rather than waiting forever -- but it is a real inconsistency and must be loud.
        tracing::error!(error = %e, %message_id, %correlation_id, "command journal: complete() failed -- terminal status not persisted");
    }
    bus.publish(infrastructure::OperationUpdate { message_id, correlation_id, status, error_code, message });
}

/// `CommandJournalStatus` → the `command_completion_ms{status}` label the contract names
/// (SUCCEEDED | REJECTED | FAILED). RECEIVED cannot reach here: it is not terminal.
fn journal_status_label(s: domain::generated::scalars::CommandJournalStatus) -> &'static str {
    use domain::generated::scalars::CommandJournalStatus as J;
    match s {
        J::RECEIVED => "RECEIVED",
        J::SUCCEEDED => "SUCCEEDED",
        J::REJECTED => "REJECTED",
        J::FAILED => "FAILED",
    }
}

fn internal_completion() -> (
    domain::generated::scalars::CommandJournalStatus,
    Option<serde_json::Value>,
    Option<String>,
    Option<String>,
) {
    let def = domain::generated::errors::INTERNAL;
    (
        domain::generated::scalars::CommandJournalStatus::FAILED,
        Some(serde_json::json!({ "code": def.code, "context": {} })),
        Some(def.code.to_string()),
        Some(def.message_en.to_string()),
    )
}

/// The synchronous Conflict for a replayed messageId whose payload differs — a client bug, not a
/// retry (ADR-20260720-015300); errors.yaml cross-cutting `Conflict`, P-10 extensions shape.
fn conflict_error(message_id: uuid::Uuid) -> async_graphql::Error {
    use async_graphql::ErrorExtensions;
    let def = domain::generated::errors::CONFLICT;
    async_graphql::Error::new(format!(
        "messageId {message_id} was already used with a different payload"
    ))
    .extend_with(|_, ext| ext.set("code", def.code))
}

/// Map a SYNCHRONOUS failure (journal insert, input deserialization) onto the GraphQL error
/// contract (P-10): an anticipated errors.yaml rejection surfaces `extensions.code` = the stable
/// PascalCase code, the interpolated English message as the error message, and its typed context
/// fields under the extensions; anything unexpected (repository/adapter failures) surfaces as the
/// generic catalogued `Internal` — never leaking adapter details to the client.
fn domain_error(e: domain::shared::errors::DomainError) -> async_graphql::Error {
    use async_graphql::ErrorExtensions;
    use domain::shared::errors::DomainError;
    match e {
        DomainError::Rejected { code, context } => {
            let message = domain::generated::errors::message_en(&code, &context)
                .unwrap_or_else(|| code.clone());
            async_graphql::Error::new(message).extend_with(|_, ext| {
                ext.set("code", code.as_str());
                if let Some(fields) = context.as_object() {
                    for (key, value) in fields {
                        if key == "code" {
                            continue; // never let a context field shadow the wire code
                        }
                        ext.set(
                            key.as_str(),
                            async_graphql::Value::from_json(value.clone())
                                .unwrap_or(async_graphql::Value::Null),
                        );
                    }
                }
            })
        }
        // Legacy "<Code>: <detail>" string invariants (interim adapters, e.g. the fail-closed
        // payment stand-in): surface the prefix when it is a catalogued code, else it is unexpected.
        DomainError::Invariant(msg) => {
            let code = msg.split(':').next().map(str::trim).unwrap_or("").to_string();
            if domain::generated::errors::find(&code).is_some() {
                async_graphql::Error::new(msg).extend_with(|_, ext| ext.set("code", code.as_str()))
            } else {
                internal_error()
            }
        }
        DomainError::Repository(_) => internal_error(),
    }
}

/// The generic catalogued `Internal` fallback (errors.yaml): unexpected/infrastructure failures
/// never leak their detail to the client.
fn internal_error() -> async_graphql::Error {
    use async_graphql::ErrorExtensions;
    let def = domain::generated::errors::INTERNAL;
    async_graphql::Error::new(def.message_en).extend_with(|_, ext| ext.set("code", def.code))
}
